mapper.select:
SELECT d.id, d.workitem_id, d.status, d.gmt_create, d.gmt_modified, w.title, a.name AS agent_name, COALESCE(entry.sdlc_id, av.sdlc_id) AS sdlc_id, s.name AS sdlc_name FROM dispatch d JOIN workitem w ON w.id = d.workitem_id AND w.tenant_id = d.tenant_id AND w.is_deleted = 0 LEFT JOIN sdlc_step entry ON entry.id = d.sdlc_step_id AND entry.tenant_id = d.tenant_id LEFT JOIN agent_version av ON av.id = d.agent_version_id AND av.tenant_id = d.tenant_id AND av.agent_id = d.agent_id LEFT JOIN sdlc s ON s.id = COALESCE(entry.sdlc_id, av.sdlc_id) AND s.tenant_id = d.tenant_id LEFT JOIN agent a ON a.id = d.agent_id AND a.tenant_id = d.tenant_id WHERE d.tenant_id = #{tenantId} AND d.is_deleted = 0
AND d.gmt_create >= #{start} AND d.gmt_create < #{end}
AND EXISTS (SELECT 1 FROM squad_member sm JOIN squad sq ON sq.id = sm.squad_id AND sq.tenant_id = sm.tenant_id WHERE sm.tenant_id = d.tenant_id AND sm.agent_id = d.agent_id AND sm.squad_id = #{squadId} AND sq.is_deleted = 0)
AND COALESCE(entry.sdlc_id, av.sdlc_id) = #{sdlcId} ORDER BY d.gmt_create DESC, d.id DESC LIMIT #{limit}
